SELECT id, decision, original_decision, final_entry_allowed, primary_blocking_stage, LEFT(final_decision_explanation,1500) AS final_expl, decision_path FROM crypto_ai.trade_signal WHERE id=176655;
SELECT CASE WHEN w.execution_message LIKE '%BALANCED_NEUTRAL_5M_WATCH_1H%' THEN 'FIX11G' WHEN w.execution_reason='ACCUMULATED_EVIDENCE' AND w.execution_message LIKE '%LATE_ENTRY%' THEN 'ACCUM_LATE' WHEN w.execution_reason='ACCUMULATED_EVIDENCE' THEN 'ACCUM_OTHER' ELSE w.execution_reason END AS route, COUNT(*) AS buys, SUM(p.realized_pnl < 0) AS losers, ROUND(SUM(p.realized_pnl),6) AS pnl_sum, ROUND(AVG(m.entry_quality_score),1) AS avg_eq FROM crypto_ai.wallet_trade w LEFT JOIN crypto_ai.paper_position p ON p.signal_id=w.signal_id AND p.status IN ('CLOSED','STOPPED') LEFT JOIN crypto_ai.wallet_managed_position m ON m.entry_signal_id=w.signal_id WHERE w.side='BUY' AND w.status='EXECUTED' GROUP BY route ORDER BY pnl_sum;